<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(isset($_POST['guardar'])){
    $id=(int)($_POST['id']??0);$cot=(int)($_POST['cotizacion_id']??0);$titulo=epost('titulo');if($titulo==='')$titulo='Trabajo SRNU';
    $data=[$cot?:null,$titulo,epost('fecha_inicio',date('Y-m-d')),epost('hora_inicio')?:null,epost('fecha_entrega')?:null,epost('hora_entrega')?:null,epost('responsable'),epost('estado','Programado'),efloat('duracion_estimada_horas'),epost('notas')];
    if($id){$pdo->prepare('UPDATE agenda_trabajos SET cotizacion_id=?,titulo=?,fecha_inicio=?,hora_inicio=?,fecha_entrega=?,hora_entrega=?,responsable=?,estado=?,duracion_estimada_horas=?,notas=? WHERE id=?')->execute([...$data,$id]);}
    else{$pdo->prepare('INSERT INTO agenda_trabajos(cotizacion_id,titulo,fecha_inicio,hora_inicio,fecha_entrega,hora_entrega,responsable,estado,duracion_estimada_horas,notas) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($data);}
  }
  if(isset($_POST['eliminar']))$pdo->prepare('DELETE FROM agenda_trabajos WHERE id=?')->execute([(int)$_POST['id']]);
  ego('agenda.php?mes='.urlencode($_POST['mes']??date('Y-m')));
}
$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$inicio=$mes.'-01';$fin=date('Y-m-t',strtotime($inicio));
$q=$pdo->prepare("SELECT a.*,c.folio,c.cliente,c.vehiculo,(SELECT COUNT(*) FROM cotizacion_items ci WHERE ci.cotizacion_id=a.cotizacion_id AND ci.tipo_entrega='sobre_pedido') sobre_pedido FROM agenda_trabajos a LEFT JOIN cotizaciones c ON c.id=a.cotizacion_id WHERE a.fecha_inicio<=? AND COALESCE(a.fecha_entrega,a.fecha_inicio)>=? ORDER BY a.fecha_inicio,a.hora_inicio");$q->execute([$fin,$inicio]);$events=$q->fetchAll();
$by=[];foreach($events as $e){$d=$e['fecha_inicio'];$last=$e['fecha_entrega']?:$d;for($ts=strtotime($d),$end=strtotime($last);$ts<=$end && $ts<=strtotime($fin);$ts+=86400){$day=date('Y-m-d',$ts);if($day>=$inicio)$by[$day][]=$e;}}
$cots=srnu_get_cotizaciones_select();$prefill=(int)($_GET['cotizacion_id']??0);$days=(int)date('t',strtotime($inicio));$first=(int)date('N',strtotime($inicio));
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda · SRNU</title><link rel="icon" href="favicon.png"><?=srnu_ui_head()?></head><body><?php srnu_appbar('agenda');?><main class="w"><div class="srnu-page-heading"><div><h1>Agenda de trabajos</h1><p>Ingresos, entregas, responsables y trabajos sobre pedido.</p></div></div><section class="panel" style="padding:18px"><form method="post" class="erp-form cols-4"><input type="hidden" name="mes" value="<?=eh($mes)?>"><select name="cotizacion_id"><option value="">Sin cotización ligada</option><?php foreach($cots as $c):?><option value="<?=$c['id']?>" <?=$prefill===$c['id']?'selected':''?>><?=eh(srnu_cotizacion_label($c))?></option><?php endforeach;?></select><input name="titulo" placeholder="Título / trabajo"><input type="date" name="fecha_inicio" value="<?=date('Y-m-d')?>"><input type="time" name="hora_inicio"><input type="date" name="fecha_entrega"><input type="time" name="hora_entrega"><select name="responsable"><option value="">Responsable</option><option>Sergio</option><option>Ricardo</option><option>Tomás</option><option>Equipo</option></select><select name="estado"><option>Programado</option><option>En proceso</option><option>Esperando producto</option><option>Listo</option><option>Entregado</option><option>Cancelado</option></select><input type="number" step="0.5" min="0" name="duracion_estimada_horas" placeholder="Horas estimadas"><input class="full" name="notas" placeholder="Notas"><button class="btn blue" name="guardar" value="1">Agregar a agenda</button></form></section><div class="toolbar" style="margin:16px 0"><a class="btn light" href="?mes=<?=date('Y-m',strtotime($inicio.' -1 month'))?>">← Mes anterior</a><form><input type="month" name="mes" value="<?=eh($mes)?>"><button class="btn">Ir</button></form><a class="btn light" href="?mes=<?=date('Y-m',strtotime($inicio.' +1 month'))?>">Mes siguiente →</a></div><section class="calendar-grid"><?php for($i=1;$i<$first;$i++):?><div></div><?php endfor;?><?php for($d=1;$d<=$days;$d++):$date=$mes.'-'.str_pad((string)$d,2,'0',STR_PAD_LEFT);?><div class="calendar-day"><div class="n"><?=$d?></div><?php foreach($by[$date]??[] as $e):?><div class="calendar-event"><b><?=eh($e['titulo'])?></b><?php if($e['cliente']):?><div><?=eh($e['cliente'])?> · <?=eh($e['vehiculo'])?></div><?php endif;?><div><?=eh($e['responsable']?:'Sin responsable')?> · <?=eh($e['estado'])?></div><?php if((int)$e['sobre_pedido']>0):?><span class="badge badge-orange">Sobre pedido</span><?php endif;?></div><?php endforeach;?></div><?php endfor;?></section><section class="tablebox" style="margin-top:18px"><table><thead><tr><th>Fechas</th><th>Trabajo</th><th>Cliente</th><th>Responsable</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?=edate($e['fecha_inicio'])?> <?=eh(substr((string)$e['hora_inicio'],0,5))?><div class="muted">Entrega: <?=edate($e['fecha_entrega'])?></div></td><td><b><?=eh($e['titulo'])?></b><?php if((int)$e['sobre_pedido']>0):?> <span class="badge badge-orange">Sobre pedido</span><?php endif;?><div class="muted"><?=eh($e['notas'])?></div></td><td><?=eh($e['cliente'])?><div class="muted"><?=eh($e['vehiculo'])?></div></td><td><?=eh($e['responsable'])?></td><td><?=eh($e['estado'])?></td><td><?php if($e['cotizacion_id']):?><a class="btn light" href="cotizador.php?id=<?=$e['cotizacion_id']?>">Cotización</a><?php endif;?><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=$e['id']?>"><input type="hidden" name="mes" value="<?=eh($mes)?>"><button class="btn danger" name="eliminar" value="1" onclick="return confirm('¿Eliminar evento?')">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
